// ===== 실패 알림을 받을 Discord 웹훅 =====
const DISCORD_WEBHOOK_URL = '';

if (!DISCORD_WEBHOOK_URL) return [];
const d = $input.first().json || {};
const ex = d.execution || {};
const err = ex.error || {};
const node = ex.lastNodeExecuted || (err.node && err.node.name) || '알 수 없음';
const msg = String(err.message || err.description || '오류 메시지 없음').slice(0, 900);

const HINTS = {
  'RSS 읽기': '모든 피드가 실패했다면 n8n 네트워크 문제일 수 있습니다. 잠시 뒤 다시 실행하세요.',
  '기사 정리': '모든 피드·네이버 요청이 실패했습니다. 오류 메시지의 피드별 결과를 보고 "설정" 노드의 주소나 네이버 자격 증명을 확인하세요.',
  '네이버 뉴스': '네이버 자격 증명(Client ID·Secret)을 확인하세요.',
  '이미 저장된 기사': 'Supabase 주소, 자격 증명, schema.sql 실행 여부(existing_url_keys 함수)를 확인하세요.',
  'Supabase 저장': 'Supabase 자격 증명과 articles 테이블을 확인하세요. 401이면 키 문제입니다.',
  '새 기사 조회': 'Supabase 주소·자격 증명을 확인하세요.',
  '오늘 게시분 조회': 'Supabase 주소·자격 증명을 확인하세요.',
  '오늘 브리핑 조회': 'Supabase 주소·자격 증명을 확인하세요.',
  'Gemini 요약·평가': '404면 "설정" 노드 geminiModel을 새 모델 이름으로, 400이면 "프롬프트 생성"의 thinkingConfig 줄을 지우세요. 429는 사용량 한도입니다.',
  'Gemini 예비 모델': 'AI Studio 모델 목록에서 flash-lite 계열 이름을 찾아 "설정" 노드 fallbackModel에 넣으세요.',
  '다이제스트 생성': '"Gemini 요약이 모두 실패"면 30분쯤 뒤 수동 재실행. JSON 관련 오류면 "설정" 노드 maxPerEdition을 60으로 줄이세요.',
  '기사 저장': 'Supabase articles 테이블 열 이름과 자격 증명을 확인하세요.',
  '브리핑 저장': 'Supabase reports 테이블을 확인하세요.',
  'GitHub 기존 파일 확인': '401·403이면 GitHub 토큰 만료 또는 권한(Contents Read and write)을 확인하세요.',
  'GitHub 커밋': '404면 "설정" 노드 githubOwner·githubRepo·githubBranch, 409·422면 다시 실행하세요.',
  '임베딩': '"설정" 노드 embeddingModel 이름과 Gemini 키를 확인하세요. 사이트 게시는 이미 끝났습니다.',
  '지식베이스 저장 준비': 'embedDim과 Supabase kb_chunks 벡터 크기(768)가 같은지 확인하세요.',
  '볼트 파일 목록': '404면 "설정" 노드 vaultRepo·vaultBranch와 GitHub 토큰에 볼트 저장소 권한이 있는지, 저장소가 README로 초기화됐는지 확인하세요. 사이트 게시는 이미 끝났습니다.',
  '볼트 기준 커밋': '볼트 저장소가 비어 있으면 README 하나를 만들어 초기화하세요.',
  '옵시디안 노트 만들기': '볼트 저장소를 읽지 못했습니다. 저장소 이름과 토큰 권한을 확인하세요.',
  '볼트 트리 만들기': 'GitHub 토큰에 볼트 저장소 Contents 쓰기 권한이 있는지 확인하세요.',
  '볼트 커밋 만들기': 'GitHub 토큰 권한을 확인한 뒤 다시 실행하세요.',
  '볼트 반영': '422(fast forward 아님)면 옵시디안에서 같은 시각에 push한 경우입니다. 게시 워크플로를 다시 실행하면 됩니다.',
  '지식베이스 저장': 'Supabase kb_chunks 테이블과 vector 확장을 확인하세요. 사이트 게시는 이미 끝났습니다.',
};
const kst = new Date(Date.now() + 9 * 3600_000).toISOString().replace('T', ' ').slice(0, 16);
const fields = [
  { name: '워크플로', value: String((d.workflow && d.workflow.name) || '?'), inline: true },
  { name: '멈춘 노드', value: node, inline: true },
  { name: '시각 (KST)', value: kst, inline: true },
  { name: '오류', value: '```' + msg.replace(/```/g, "'''") + '```' },
  { name: '처치', value: HINTS[node] || '실행 기록에서 빨간 노드를 열어 오류를 확인한 뒤 다시 실행하세요.' },
];
if (ex.url) fields.push({ name: '실행 기록', value: ex.url });
return [{ json: { webhook: DISCORD_WEBHOOK_URL, payload: { username: '투자 뉴스 브리프', embeds: [{ title: '⚠️ 워크플로가 멈췄습니다', color: 0xd7263d, fields }] } } }];
